System.register([],function(n,i){"use strict";return{execute:function(){n("default",'# 📘 第11章 二维数组\n\n> 目标：掌握二维数组的声明、访问与常见操作\n\n---\n\n## 11.1 概念与声明\n```cpp\nint a[3][4];                  // 3 行 4 列\nint b[2][3] = {{1,2,3},{4,5,6}};\ncout << b[1][2] << endl;      // 输出 6\n```\n- 连续存储，按行优先（row-major）\n\n---\n\n## 11.2 应用实例：矩阵行列和\n```cpp\nint n, m; cin >> n >> m;\nint sRow[110]={0}, sCol[110]={0};\nfor (int i = 0; i < n; i++) {\n    for (int j = 0; j < m; j++) {\n        int x; cin >> x;\n        sRow[i] += x; sCol[j] += x;\n    }\n}\nfor (int i = 0; i < n; i++) cout << sRow[i] << " ";\ncout << "\\n";\nfor (int j = 0; j < m; j++) cout << sCol[j] << " ";\n```\n\n---\n\n## 小练习\n1) 给定 n×m 矩阵，求主对角线与副对角线元素之和\n2) 计算矩阵转置并输出\n')}}});
